import csv
cool='f0c17382-5dc5-5762-aef6-7d433ca8d7bb'
temp='f9990edd-406b-5118-8fc2-62ecc998fe86'
cd={}; td={}
for r in csv.DictReader(open(VALUES_CSV, newline='', encoding='utf-8')):
    v=r['timeseries_id']
    if v==cool: cd[r['timestamp']]=float(r['value'])
    elif v==temp: td[r['timestamp']]=float(r['value'])
def hour(d,h): return f"{d}T{h:02d}:00:00"
for d in ("2018-01-23","2018-04-13"):
    devs=[]
    for h in range(8,19):
        t=hour(d,h)
        if t in td and t in cd:
            devs.append(td[t]-cd[t])
    print(d, len(devs), sum(devs)/len(devs), devs)
